package vn.contractgovernance.api.privacy;
import java.util.*;
import java.time.*;
import org.springframework.stereotype.Service;
import tools.jackson.databind.JsonNode;
import tools.jackson.databind.node.ObjectNode;
import vn.contractgovernance.api.shared.*;
import vn.contractgovernance.api.files.*;
import vn.contractgovernance.api.customer.*;
import vn.contractgovernance.api.identity.UserDirectory;
import static vn.contractgovernance.api.obligation.DutyEvidence.id;
/** Explicit File/Relationship resolver; no arbitrary JSON document mutation or role inheritance. */
@Service public class PrivacyRecords {
 public final EntityStore store;public final JsonSupport json;public final Clock clock;
 private final EvidenceAccess access;private final CustomerAccess customers;private final ContactCorrectionProof contacts;private final FileDispositions files;private final UserDirectory users;private final DispositionLocks locks;
 private final ThreadLocal<Set<UUID>> visiting=ThreadLocal.withInitial(HashSet::new);
 public PrivacyRecords(EntityStore store,JsonSupport json,Clock clock,EvidenceAccess access,CustomerAccess customers,ContactCorrectionProof contacts,FileDispositions files,UserDirectory users,DispositionLocks locks){this.store=store;this.json=json;this.clock=clock;this.access=access;this.customers=customers;this.contacts=contacts;this.files=files;this.users=users;this.locks=locks;}
 public Actor current(Actor a){return users.actor(a.id());}
 public Set<UUID> contributors(EntityStore.Entity request){var result=new TreeSet<UUID>();request.body().path("contributorIds").forEach(v->result.add(UUID.fromString(v.asString())));for(var value:request.body().path("recordIds")){UUID rid=UUID.fromString(value.asString());var target=store.find("File",rid).orElseGet(()->store.require("Relationship",rid));sourceContributors(target,result);if(target.type().equals("Relationship")){var rows=store.jdbc().query("select e.body::text from cg_customer_contact_history h join cg_entity e on e.entity_type='ContactRequest' and e.id=h.request_id where h.relationship_id=? and h.contact_version=?",(rs,n)->json.parse(rs.getString(1)),target.id(),target.body().path("contactVersion").asInt());for(var body:rows)body.path("contributorIds").forEach(v->result.add(UUID.fromString(v.asString())));}}store.jdbc().query("select body::text from cg_entity where entity_type='File' and body->>'targetKind'='DATA_REQUEST' and body->>'targetId'=?",(rs,n)->json.parse(rs.getString(1)),request.id().toString()).forEach(body->{if(body.hasNonNull("uploadedBy"))result.add(UUID.fromString(body.path("uploadedBy").asString()));});return result;}
 private void sourceContributors(EntityStore.Entity target,Set<UUID> result){target.body().path("contributorIds").forEach(v->result.add(UUID.fromString(v.asString())));if(target.body().hasNonNull("uploadedBy"))result.add(UUID.fromString(target.body().path("uploadedBy").asString()));}
 public void currentGrants(EntityStore.Entity request,Actor actor){actor=current(actor);for(var value:(request.body().hasNonNull("manifest")?request.body().path("manifest").path("records"):request.body().path("recordIds"))){var target=resolve(UUID.fromString(value.isObject()?value.path("recordId").asString():value.asString()),actor);if(target.type().equals("File"))access.requireFull(target,actor);}}
 public EntityStore.Entity resolve(UUID id,Actor a){a=current(a);var file=store.find("File",id);if(file.isPresent()){var f=access.requireFile(id,a);return f;}var relationship=store.find("Relationship",id);if(relationship.isPresent())return customers.requireRelationship(id,a);throw ApiException.of("NOT_FOUND","Privacy record chỉ hỗ trợ File hoặc current Relationship trong scope.");}
 public EntityStore.Entity request(UUID id,Actor a){a=current(a);a.requireRole("MAKER","DATA_OFFICER","AUDITOR");var r=store.require("DataRequest",id);a.requireBranch(r.branchId());var seen=visiting.get();if(!seen.add(id)||seen.size()>16)throw ApiException.of("NOT_FOUND","Invalid privacy record ancestry.");try{for(var value:r.body().path("recordIds")){var target=resolve(UUID.fromString(value.asString()),a);if(!Objects.equals(target.branchId(),r.branchId()))throw ApiException.of("NOT_FOUND","Record khác branch.");}return r;}finally{seen.remove(id);if(seen.isEmpty())visiting.remove();}}
 public void lockRecords(JsonNode ids){store.jdbc().queryForObject("select pg_advisory_xact_lock(hashtextextended('privacy-records',0))",Object.class);var contracts=new TreeSet<UUID>();var relationships=new TreeSet<UUID>();for(var value:ids){UUID id=UUID.fromString(value.asString());var file=store.find("File",id);if(file.isPresent())contracts.addAll(contracts(file.get()));else if(store.find("Relationship",id).isPresent())relationships.add(id);else throw ApiException.of("NOT_FOUND","Unsupported record.");}var dossiers=new TreeSet<UUID>();for(var id:contracts)dossiers.add(id(store.require("Contract",id).body(),"dossierId"));for(var id:dossiers)store.lock("Dossier",id);for(var id:contracts)store.lock("Contract",id);for(var id:relationships)store.lock("Relationship",id);var sorted=new TreeSet<UUID>();ids.forEach(v->sorted.add(UUID.fromString(v.asString())));for(var id:sorted){store.jdbc().queryForObject("select pg_advisory_xact_lock(hashtextextended(?,0))",Object.class,"record:"+id);if(store.find("File",id).isPresent())store.lock("File",id);}}
 public Set<UUID> contracts(EntityStore.Entity file){String kind=file.body().path("targetKind").asString();UUID parent=id(file.body(),"targetId");if(kind.equals("CONTRACT"))return Set.of(parent);String type=switch(kind){case "DOSSIER"->"Dossier";case "CHANGE"->"Change";case "NOTICE"->"Notice";case "INCIDENT"->"Incident";case "OBLIGATION"->"Obligation";case "CONTROL_REQUEST"->"ControlRequest";case "RELATIONSHIP"->"Relationship";default->null;};if(type==null)return Set.of();var entity=store.require(type,parent);if(entity.body().hasNonNull("contractId"))return Set.of(id(entity.body(),"contractId"));String field=kind.equals("DOSSIER")?"dossierId":"relationshipId";return new TreeSet<>(store.jdbc().query("select id from cg_entity where entity_type='Contract' and body->>?=? order by id",(rs,n)->rs.getObject(1,UUID.class),field,parent.toString()));}
 public void available(UUID record){if(store.jdbc().queryForObject("select case when cg_disposition_pending(?) then 1 else 0 end",Long.class,record)>0)throw ApiException.of("DISPOSITION_COMMITTED","Record đã có committed disposition.");}
 public void holds(UUID record){if(store.jdbc().queryForObject("select count(*) from cg_record_hold_member m join cg_record_hold h on h.id=m.hold_id where m.record_id=? and h.released_at is null",Long.class,record)>0)throw ApiException.of("HOLD_ACTIVE","Record đang có active hold.");}
 public JsonNode proof(EntityStore.Entity request,JsonNode record,Actor officer,boolean mutation){UUID rid=id(record,"recordId");var target=resolve(rid,officer);if(PrivacyService.exactVersion(record.path("expectedRecordVersion"))!=target.version())throw ApiException.of("BASE_CONFLICT","Privacy expectedRecordVersion không còn hiện hành.");String action=record.path("action").asString();var p=json.object();p.put("recordId",rid.toString()).put("type",target.type()).put("version",target.version());if(action.equals("CORRECT_CURRENT_METADATA")){if(!record.path("recordClass").asString().equals("DEMO_OPERATION")||!target.type().equals("Relationship")||!record.hasNonNull("correction")||record.hasNonNull("replacementFileId"))throw ApiException.validation("/manifest/records","Correction chỉ current Relationship với Contact đầy đủ.");if(!target.body().path("confirmedContact").path("purpose").equals(record.path("correction").path("purpose")))throw ApiException.validation("/manifest/records/correction/purpose","Không đổi purpose.");p.set("contactProof",contacts.verified(target,record.path("correction")));}else{if(!target.type().equals("File")||record.hasNonNull("correction"))throw ApiException.validation("/manifest/records","Byte disposition chỉ File.");access.requireFull(target,officer);String cls=classification(target);if(!record.path("recordClass").asString().equals(cls))throw ApiException.validation("/manifest/records/recordClass","Class không khớp actual source/purpose.");p.set("file",files.proof(target));p.set("retentionReview",eligibility(target,cls));if(action.equals("DELETE_BYTES")){if(record.hasNonNull("replacementFileId"))throw ApiException.validation("/manifest/records/replacementFileId","DELETE_BYTES không có replacement.");}else{if(!record.hasNonNull("replacementFileId"))throw ApiException.of("READINESS_BLOCKED","Cần safe copy đã upload và được officer độc lập xét.");var copy=access.requireClean(id(record,"replacementFileId"),"DATA_REQUEST",request.id(),request.branchId(),officer);access.requireFull(copy,officer);if(copy.id().equals(target.id()))throw ApiException.validation("/manifest/records/replacementFileId","Safe copy phải là File khác.");if(copy.body().hasNonNull("uploadedBy")&&copy.body().path("uploadedBy").asString().equals(officer.id().toString()))throw ApiException.of("SOD_VIOLATION","Officer không tự review copy do mình upload.");p.set("replacement",files.proof(copy));if(mutation){store.jdbc().update("insert into cg_file_association(file_id,target_type,target_id,historical,created_at) values(?,'DATA_REQUEST',?,true,?) on conflict(file_id,target_type,target_id) do update set historical=true",copy.id(),request.id(),java.sql.Timestamp.from(clock.instant()));if(!copy.body().path("attached").asBoolean()){var b=(ObjectNode)copy.body().deepCopy();b.put("attached",true).put("updatedAt",now());var updated=store.update(copy,b);((ObjectNode)p.path("replacement")).put("version",updated.version());}}}}return p;}
 public String classification(EntityStore.Entity f){return switch(f.body().path("purpose").asString()){case "IDENTITY_IMAGE"->"DEMO_ID_COPY";case "SERVICE_APPLICATION","CORPORATE_ID","REPRESENTATION_BASIS","SERVICE_TERMS","SIGNING_COPY"->"DEMO_AGREEMENT";default->"DEMO_OPERATION";};}
 public JsonNode eligibility(EntityStore.Entity file,String cls){var cs=contracts(file);var result=json.object().put("recordClass",cls).put("syntheticOnly",true).put("reviewEligible",false);if(cs.isEmpty()){result.putNull("eligibleAt");return result;}Instant anchor=null;for(var c:cs){List<Instant> times;if(cls.equals("DEMO_ID_COPY"))times=store.jdbc().query("select max(verified_at) from (select a.assessed_at verified_at from cg_signing_assessment a join cg_signing_input i on i.packet_id=a.packet_id join cg_original_agreement o on o.contract_id=i.contract_id where i.contract_id=? and exists(select 1 from jsonb_array_elements(o.source->'revision'->'documents') d where d->>'fileId'=?) union all select a.assessed_at from cg_change_signing_assessment a join cg_change_signing_input i on i.packet_id=a.packet_id join cg_change_revision v on v.id=i.revision_id join cg_entity ch on ch.entity_type='Change' and ch.id=i.change_id where ch.body->>'contractId'=? and exists(select 1 from jsonb_array_elements(v.revision->'documents') d where d->>'fileId'=?)) verified",(rs,n)->rs.getTimestamp(1)==null?null:rs.getTimestamp(1).toInstant(),c,file.id().toString(),c.toString(),file.id().toString());else times=store.jdbc().query("select max(v.recorded_at) from cg_g5_event v join cg_entity o on o.entity_type='Obligation' and o.id=v.target_id where v.target_type='Obligation' and v.kind='ACCEPT_SUBMISSION' and o.body->>'type'='CLOSEOUT' and o.body->>'state'='CLOSED' and o.body->>'contractId'=?",(rs,n)->rs.getTimestamp(1)==null?null:rs.getTimestamp(1).toInstant(),c.toString());if(times.isEmpty()||times.getFirst()==null){result.putNull("eligibleAt");return result;}var time=times.getFirst();if(anchor==null||time.isAfter(anchor))anchor=time;}var eligible=anchor.plus(Duration.ofDays(cls.equals("DEMO_ID_COPY")?30:cls.equals("DEMO_AGREEMENT")?3650:180));result.put("eligibleAt",JsonSupport.timestamp(eligible)).put("reviewEligible",!clock.instant().isBefore(eligible));return result;}
 public String now(){return JsonSupport.timestamp(clock.instant());}
}
